#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <limits.h>
#include <string.h>

typedef struct { const char *s; size_t p, n; } Parser;

static void ws(Parser *p) { while (p->p < p->n && isspace((unsigned char)p->s[p->p])) p->p++; }
static void expect(Parser *p, char c) { ws(p); if (p->p >= p->n || p->s[p->p++] != c) exit(2); }
static int read_int(Parser *p) {
    ws(p); int sign = 1;
    if (p->s[p->p] == '-') { sign = -1; p->p++; }
    int v = 0;
    while (p->p < p->n && isdigit((unsigned char)p->s[p->p])) v = v * 10 + (p->s[p->p++] - '0');
    return sign * v;
}
static int *read_array(Parser *p, int *len) {
    expect(p,'['); ws(p);
    if (p->s[p->p] == ']') { p->p++; *len = 0; return NULL; }
    int cap=4, n=0; int *a=(int*)malloc(cap*sizeof(int));
    while (1) {
        if(n==cap){cap*=2;a=(int*)realloc(a,cap*sizeof(int));}
        a[n++]=read_int(p); ws(p);
        if(p->s[p->p]==']'){p->p++;break;} expect(p,',');
    }
    *len=n; return a;
}
static int **read_matrix(Parser *p, int *rows, int **cols) {
    expect(p,'['); ws(p);
    if(p->s[p->p]==']'){p->p++;*rows=0;*cols=NULL;return NULL;}
    int cap=8,n=0; int **m=(int**)malloc(cap*sizeof(int*)); int *cs=(int*)malloc(cap*sizeof(int));
    while(1){
        if(n==cap){cap*=2;m=(int**)realloc(m,cap*sizeof(int*));cs=(int*)realloc(cs,cap*sizeof(int));}
        m[n]=read_array(p,&cs[n]); n++; ws(p);
        if(p->s[p->p]==']'){p->p++;break;} expect(p,',');
    }
    *rows=n; *cols=cs; return m;
}

/* User-facing LeetCode-style function signature. */
int shortestDistance(int **maze, int mazeSize, int *mazeColSize,
                     int *start, int startSize, int *destination, int destinationSize) {
    (void)startSize; (void)destinationSize;
    int rows=mazeSize, cols=mazeColSize[0];
    int *dist=(int*)malloc((size_t)rows*cols*sizeof(int));
    for(int i=0;i<rows*cols;i++) dist[i]=INT_MAX;
    int sr=start[0], sc=start[1], tr=destination[0], tc=destination[1];

    /* O((rc) log(rc)) Dijkstra with at most four rolls per stop. */
    typedef struct { int d,r,c; } State;
    State *heap=(State*)malloc((size_t)(rows*cols*4+4)*sizeof(State));
    int h=0;
    #define SWAP(a,b) do{State tmp=(a);(a)=(b);(b)=tmp;}while(0)
    #define PUSH(x) do{int i=h++;heap[i]=(x);while(i>0){int q=(i-1)/2;if(heap[q].d<=heap[i].d)break;SWAP(heap[q],heap[i]);i=q;}}while(0)
    #define POP(out) do{(out)=heap[0];heap[0]=heap[--h];int i=0;while(1){int l=2*i+1,r=l+1,m=i;if(l<h&&heap[l].d<heap[m].d)m=l;if(r<h&&heap[r].d<heap[m].d)m=r;if(m==i)break;SWAP(heap[i],heap[m]);i=m;}}while(0)

    dist[sr*cols+sc]=0; PUSH(((State){0,sr,sc}));
    int dr[4]={-1,1,0,0}, dc[4]={0,0,-1,1};
    while(h){
        State cur; POP(cur);
        if(cur.d!=dist[cur.r*cols+cur.c]) continue;
        if(cur.r==tr && cur.c==tc){int ans=cur.d;free(dist);free(heap);return ans;}
        for(int k=0;k<4;k++){
            int nr=cur.r,nc=cur.c,nd=cur.d;
            while(nr+dr[k]>=0&&nr+dr[k]<rows&&nc+dc[k]>=0&&nc+dc[k]<cols&&maze[nr+dr[k]][nc+dc[k]]==0){
                nr+=dr[k];nc+=dc[k];nd++;
            }
            if(nd<dist[nr*cols+nc]){
                dist[nr*cols+nc]=nd;
                PUSH(((State){nd,nr,nc}));
            }
        }
    }
    free(dist);free(heap);return -1;
}

