class Solution {
    public int shortestDistance(int[][] maze, int[] start, int[] destination) {
        int rows = maze.length, cols = maze[0].length;
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        PriorityQueue<State> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.d));
        dist[start[0]][start[1]] = 0;
        pq.offer(new State(0, start[0], start[1]));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.d != dist[cur.r][cur.c]) continue;
            if (cur.r == destination[0] && cur.c == destination[1]) return cur.d;

            for (int k = 0; k < 4; k++) {
                int nr = cur.r, nc = cur.c, nd = cur.d;
                while (nr + dr[k] >= 0 && nr + dr[k] < rows &&
                       nc + dc[k] >= 0 && nc + dc[k] < cols &&
                       maze[nr + dr[k]][nc + dc[k]] == 0) {
                    nr += dr[k];
                    nc += dc[k];
                    nd++;
                }
                if (nd < dist[nr][nc]) {
                    dist[nr][nc] = nd;
                    pq.offer(new State(nd, nr, nc));
                }
            }
        }
        return -1;
    }

    private static class State {
        int d, r, c;
        State(int d, int r, int c) { this.d = d; this.r = r; this.c = c; }
    }
}

