const fs = require('fs');

function shortestDistance(maze, start, destination) {
    const rows = maze.length, cols = maze[0].length;
    const INF = Number.MAX_SAFE_INTEGER;
    const dist = Array.from({length: rows}, () => Array(cols).fill(INF));
    const [sr, sc] = start, [tr, tc] = destination;
    dist[sr][sc] = 0;

    // Binary min-heap of [distance, row, col].
    const heap = [];
    function push(item) {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function pop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let smallest = i, l = i * 2 + 1, r = l + 1;
                if (l < heap.length && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < heap.length && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    }

    push([0, sr, sc]);
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
    while (heap.length) {
        const [d, r, c] = pop();
        if (d !== dist[r][c]) continue;
        if (r === tr && c === tc) return d;
        for (const [dr, dc] of dirs) {
            let nr = r, nc = c, nd = d;
            while (nr + dr >= 0 && nr + dr < rows && nc + dc >= 0 && nc + dc < cols &&
                   maze[nr + dr][nc + dc] === 0) {
                nr += dr; nc += dc; nd++;
            }
            if (nd < dist[nr][nc]) {
                dist[nr][nc] = nd;
                push([nd, nr, nc]);
            }
        }
    }
    return -1;
}

