public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        ObjectParser p = new ObjectParser(line);
        p.expect('[');
        int[][] maze = p.readIntMatrix();
        p.expect(',');
        int[] start = p.readIntArray();
        p.expect(',');
        int[] destination = p.readIntArray();
        System.out.println(new Solution().shortestDistance(maze, start, destination));
    }

    static class ObjectParser {
        final String s; int pos = 0;
        ObjectParser(String s) { this.s = s; }
        void ws() { while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++; }
        void expect(char ch) { ws(); if (s.charAt(pos++) != ch) throw new IllegalArgumentException(); }

        int readInt() {
            ws();
            int sign = 1;
            if (s.charAt(pos) == '-') { sign = -1; pos++; }
            int v = 0;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) v = v * 10 + s.charAt(pos++) - '0';
            return sign * v;
        }

        int[] readIntArray() {
            ws(); expect('['); ws();
            if (s.charAt(pos) == ']') { pos++; return new int[0]; }
            ArrayList<Integer> a = new ArrayList<>();
            while (true) {
                a.add(readInt()); ws();
                if (s.charAt(pos) == ']') { pos++; break; }
                expect(',');
            }
            int[] out = new int[a.size()];
            for (int i = 0; i < out.length; i++) out[i] = a.get(i);
            return out;
        }

        int[][] readIntMatrix() {
            ws(); expect('['); ws();
            if (s.charAt(pos) == ']') { pos++; return new int[0][0]; }
            ArrayList<int[]> rows = new ArrayList<>();
            while (true) {
                rows.add(readIntArray()); ws();
                if (s.charAt(pos) == ']') { pos++; break; }
                expect(',');
            }
            return rows.toArray(new int[0][]);
        }
    }
}

